// DataOrgMultiError is an error wrapping multiple validation errors returned
// by DataOrg.ValidateAll() if the designated constraints aren't met.
type DataOrgMultiError []error

// Error returns a concatenation of all the error messages it wraps.
func (m DataOrgMultiError) Error() string {
	msgs := make([]string, 0, len(m))
	for _, err := range m {
		msgs = append(msgs, err.Error())
	}
	return strings.Join(msgs, "; ")
}

// AllErrors returns a list of validation violation errors.
